def build_cache_key(*segments):
    """构造商品缓存键。"""
    return "".join(str(segment) for segment in segments)

verification_tests:
from target import build_cache_key


def test_different_segments_do_not_collide():
    assert build_cache_key("12", "3") != build_cache_key("1", "23")


def test_single_segment_is_representable():
    assert build_cache_key("abc") != build_cache_key("a", "bc")


def test_empty_key_for_no_segments():
    assert build_cache_key() == ""
